DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cleanup_old_sessions` ()   BEGIN
    DELETE FROM user_sessions 
    WHERE is_active = FALSE 
    AND ended_at < DATE_SUB(NOW(), INTERVAL 30 DAY);
    
    UPDATE user_sessions 
    SET is_active = FALSE, ended_at = NOW()
    WHERE is_active = TRUE 
    AND last_activity < DATE_SUB(NOW(), INTERVAL 24 HOUR);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_increase_fraud_score` (IN `p_user_id` INT(10) UNSIGNED, IN `p_amount` INT, IN `p_fraud_type` VARCHAR(50), IN `p_details` JSON)   BEGIN
    UPDATE users 
    SET fraud_score = LEAST(fraud_score + p_amount, 100)
    WHERE id = p_user_id;
    
    INSERT INTO fraud_logs (user_id, fraud_type, risk_score, details)
    VALUES (p_user_id, p_fraud_type, p_amount, p_details);
    
    IF (SELECT fraud_score FROM users WHERE id = p_user_id) >= 80 THEN
        SELECT CONCAT('User #', p_user_id, ' has high fraud score') AS alert;
    END IF;
END$$

DELIMITER ;

