--
-- Table structure for table `ads`
--

CREATE TABLE `ads` (
  `id` int(10) UNSIGNED NOT NULL,
  `type` varchar(50) NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `platform` enum('instagram','telegram','youtube','twitter','tiktok','aparat','linkedin','other') NOT NULL,
  `task_type` enum('follow','subscribe','join_channel','join_group','like','comment','view','story_view','visit','download','signup','install','review','vote','custom') NOT NULL,
  `target_url` varchar(500) NOT NULL,
  `target_username` varchar(100) DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `sample_image` varchar(500) DEFAULT NULL,
  `currency` enum('irt','usdt') NOT NULL DEFAULT 'irt',
  `price_per_task` decimal(12,4) NOT NULL,
  `total_budget` decimal(14,4) NOT NULL,
  `remaining_budget` decimal(14,4) NOT NULL,
  `site_commission_percent` decimal(5,2) NOT NULL DEFAULT 10.00,
  `tax_percent` decimal(5,2) NOT NULL DEFAULT 0.00,
  `total_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `remaining_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `completed_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `pending_count` int(10) UNSIGNED DEFAULT 0,
  `restrictions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`restrictions`)),
  `status` enum('draft','pending','active','paused','completed','rejected','cancelled','expired') NOT NULL DEFAULT 'pending',
  `rejection_reason` text DEFAULT NULL,
  `start_date` datetime DEFAULT NULL,
  `end_date` datetime DEFAULT NULL,
  `created_by` int(10) UNSIGNED DEFAULT NULL,
  `approved_by` int(10) UNSIGNED DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `image_path` varchar(500) DEFAULT NULL,
  `link` varchar(500) DEFAULT NULL,
  `placement` varchar(100) DEFAULT NULL,
  `clicks` int(10) UNSIGNED DEFAULT 0,
  `impressions` int(10) UNSIGNED DEFAULT 0,
  `ctr` decimal(5,2) DEFAULT 0.00,
  `sort_order` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `keyword` varchar(255) DEFAULT NULL,
  `site_url` varchar(500) DEFAULT NULL,
  `proof_type` varchar(50) DEFAULT NULL,
  `proof_description` text DEFAULT NULL,
  `deadline_hours` int(11) DEFAULT NULL,
  `country_restriction` varchar(200) DEFAULT NULL,
  `device_restriction` varchar(50) DEFAULT NULL,
  `os_restriction` varchar(100) DEFAULT NULL,
  `budget` decimal(14,4) DEFAULT 0.0000,
  `clicks_count` int(10) UNSIGNED DEFAULT 0,
  `deadline` datetime DEFAULT NULL,
  `price_per_click` decimal(12,4) DEFAULT 0.0000
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `alert_rules`
--

CREATE TABLE `alert_rules` (
  `id` int(10) UNSIGNED NOT NULL,
  `rule_name` varchar(255) NOT NULL,
  `rule_type` varchar(50) NOT NULL,
  `severity` enum('critical','high','medium','low') NOT NULL DEFAULT 'medium',
  `condition` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`condition`)),
  `threshold` decimal(12,2) NOT NULL DEFAULT 0.00,
  `time_window` int(10) UNSIGNED NOT NULL DEFAULT 5,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `last_triggered_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `api_tokens`
--

CREATE TABLE `api_tokens` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `name` varchar(100) NOT NULL,
  `scopes` varchar(500) DEFAULT 'read',
  `token` varchar(64) NOT NULL,
  `abilities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`abilities`)),
  `last_used_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `revoked` tinyint(1) DEFAULT 0,
  `revoked_at` timestamp NULL DEFAULT NULL,
  `use_count` int(10) UNSIGNED DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

