-- --------------------------------------------------------

--
-- Table structure for table `notification_channels`
--

CREATE TABLE `notification_channels` (
  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(150) NOT NULL,
  `channel_type` enum('telegram','email','sms','webhook') NOT NULL,
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`config`)),
  `alert_levels` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`alert_levels`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `notification_history`
--

CREATE TABLE `notification_history` (
  `id` int(10) UNSIGNED NOT NULL,
  `channel_id` int(10) UNSIGNED NOT NULL,
  `notification_type` varchar(50) NOT NULL,
  `title` varchar(255) NOT NULL,
  `message` text DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `sent_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `notification_preferences`
--

CREATE TABLE `notification_preferences` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `in_app_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `email_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `in_app_deposit` tinyint(1) NOT NULL DEFAULT 1,
  `email_deposit` tinyint(1) NOT NULL DEFAULT 1,
  `in_app_withdrawal` tinyint(1) NOT NULL DEFAULT 1,
  `email_withdrawal` tinyint(1) NOT NULL DEFAULT 1,
  `in_app_task` tinyint(1) NOT NULL DEFAULT 1,
  `email_task` tinyint(1) NOT NULL DEFAULT 0,
  `in_app_kyc` tinyint(1) NOT NULL DEFAULT 1,
  `email_kyc` tinyint(1) NOT NULL DEFAULT 1,
  `in_app_lottery` tinyint(1) NOT NULL DEFAULT 1,
  `email_lottery` tinyint(1) NOT NULL DEFAULT 0,
  `in_app_referral` tinyint(1) NOT NULL DEFAULT 1,
  `email_referral` tinyint(1) NOT NULL DEFAULT 0,
  `in_app_security` tinyint(1) NOT NULL DEFAULT 1,
  `email_security` tinyint(1) NOT NULL DEFAULT 1,
  `in_app_investment` tinyint(1) NOT NULL DEFAULT 1,
  `email_investment` tinyint(1) NOT NULL DEFAULT 1,
  `in_app_system` tinyint(1) NOT NULL DEFAULT 1,
  `email_system` tinyint(1) NOT NULL DEFAULT 0,
  `email_marketing` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

