--
-- Triggers `user_sessions`
--
DELIMITER $$
CREATE TRIGGER `tr_update_session_activity` BEFORE UPDATE ON `user_sessions` FOR EACH ROW BEGIN
    IF NEW.is_active = TRUE THEN
        SET NEW.last_activity = NOW();
    END IF;
END
$$
DELIMITER ;

