--
-- Table structure for table `withdrawal_limits`
--

CREATE TABLE `withdrawal_limits` (
  `id` int(10) UNSIGNED NOT NULL,
  `user_id` int(10) UNSIGNED NOT NULL,
  `limit_date` date NOT NULL,
  `withdrawal_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `last_withdrawal_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Structure for view `v_high_risk_users`
--
DROP TABLE IF EXISTS `v_high_risk_users`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_high_risk_users`  AS SELECT `u`.`id` AS `id`, `u`.`full_name` AS `full_name`, `u`.`email` AS `email`, `u`.`fraud_score` AS `fraud_score`, `u`.`is_blacklisted` AS `is_blacklisted`, count(distinct `fl`.`id`) AS `fraud_incidents`, max(`fl`.`created_at`) AS `last_fraud_incident` FROM (`users` `u` left join `fraud_logs` `fl` on(`u`.`id` = `fl`.`user_id`)) WHERE `u`.`fraud_score` >= 50 OR `u`.`is_blacklisted` = 1 GROUP BY `u`.`id`, `u`.`full_name`, `u`.`email`, `u`.`fraud_score`, `u`.`is_blacklisted` ORDER BY `u`.`fraud_score` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `v_today_suspicious_activities`
--
DROP TABLE IF EXISTS `v_today_suspicious_activities`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_today_suspicious_activities`  AS SELECT `fl`.`id` AS `id`, `fl`.`user_id` AS `user_id`, `fl`.`session_id` AS `session_id`, `fl`.`fraud_type` AS `fraud_type`, `fl`.`risk_score` AS `risk_score`, `fl`.`details` AS `details`, `fl`.`action_taken` AS `action_taken`, `fl`.`ip_address` AS `ip_address`, `fl`.`user_agent` AS `user_agent`, `fl`.`created_at` AS `created_at`, `u`.`full_name` AS `full_name`, `u`.`email` AS `email`, `u`.`fraud_score` AS `fraud_score` FROM (`fraud_logs` `fl` left join `users` `u` on(`fl`.`user_id` = `u`.`id`)) WHERE cast(`fl`.`created_at` as date) = curdate() ORDER BY `fl`.`created_at` DESC ;

